def solveNQueens(n):
    res = []; cols, d1, d2 = set(), set(), set()
    board = [['.']*n for _ in range(n)]
    def bt(r):
        if r == n:
            res.append([''.join(row) for row in board]); return
        for c in range(n):
            if c in cols or (r-c) in d1 or (r+c) in d2: continue
            cols.add(c); d1.add(r-c); d2.add(r+c)
            board[r][c] = 'Q'; bt(r+1); board[r][c] = '.'
            cols.discard(c); d1.discard(r-c); d2.discard(r+c)
    bt(0); return res

def solveSudoku(board):
    def valid(r, c, ch):
        for i in range(9):
            if board[r][i]==ch: return False
            if board[i][c]==ch: return False
            if board[3*(r//3)+i//3][3*(c//3)+i%3]==ch: return False
        return True
    def solve():
        for r in range(9):
            for c in range(9):
                if board[r][c]=='.':
                    for ch in '123456789':
                        if valid(r,c,ch):
                            board[r][c]=ch
                            if solve(): return True
                            board[r][c]='.'
                    return False
        return True
    solve()

def exist(board, word):
    R, C = len(board), len(board[0])
    def dfs(r, c, idx):
        if idx == len(word): return True
        if r<0 or r>=R or c<0 or c>=C or board[r][c]!=word[idx]:
            return False
        tmp, board[r][c] = board[r][c], '#'
        found = any(dfs(r+dr,c+dc,idx+1)
                     for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)])
        board[r][c] = tmp
        return found
    return any(dfs(r,c,0) for r in range(R) for c in range(C))

def partition(s):
    res = []
    def bt(start, path):
        if start == len(s): res.append(path[:]); return
        for end in range(start+1, len(s)+1):
            sub = s[start:end]
            if sub == sub[::-1]:
                path.append(sub); bt(end, path); path.pop()
    bt(0, []); return res

def generateParenthesis(n):
    res = []
    def bt(path, o, c):
        if len(path)==2*n: res.append(''.join(path)); return
        if o<n: path.append('('); bt(path,o+1,c); path.pop()
        if c<o: path.append(')'); bt(path,o,c+1); path.pop()
    bt([],0,0); return res

def letterCombinations(digits):
