def ratInMaze(maze, n):
    res = []; vis = [[False]*n for _ in range(n)]
    def solve(r, c, path):
        if r==n-1 and c==n-1: res.append(path); return
        for dr,dc,d in [(1,0,'D'),(-1,0,'U'),(0,1,'R'),(0,-1,'L')]:
            nr, nc = r+dr, c+dc
            if 0<=nr<n and 0<=nc<n and maze[nr][nc]==1 and not vis[nr][nc]:
                vis[nr][nc]=True; solve(nr,nc,path+d); vis[nr][nc]=False
    if maze[0][0]==1: vis[0][0]=True; solve(0,0,"")
    return sorted(res)

