def longestPalindrome(s):
    n=len(s); start=mx=0
    def expand(l,r):
        nonlocal start,mx
        while l>=0 and r<n and s[l]==s[r]:
            if r-l+1>mx: start,mx=l,r-l+1
            l-=1; r+=1
    for i in range(n): expand(i,i); expand(i,i+1)
    return s[start:start+mx]

