def maxProfitK(k, prices):
    n=len(prices)
    if k>=n//2:
        return sum(max(prices[i+1]-prices[i],0) for i in range(n-1))
    dp=[[0]*n for _ in range(k+1)]
    for t in range(1,k+1):
        md=-prices[0]
        for d in range(1,n):
            dp[t][d]=max(dp[t][d-1],prices[d]+md)
            md=max(md,dp[t-1][d]-prices[d])
    return dp[k][n-1]

