def maxProfitCooldown(prices):
    if len(prices)<2: return 0
    hold,sold,rest=-prices[0],0,0
    for p in prices[1:]:
        ps=sold; sold=hold+p
        hold=max(hold,rest-p); rest=max(rest,ps)
    return max(sold,rest)

