    dfs(root); return res[0]

def isSymmetric(root):
    def m(a,b):
        if not a and not b: return True
        if not a or not b: return False
        return a.val==b.val and m(a.left,b.right) and m(a.right,b.left)
    return m(root,root) if root else True

def flatten(root):
    curr=root
    while curr:
        if curr.left:
            rm=curr.left
            while rm.right: rm=rm.right
            rm.right=curr.right; curr.right=curr.left; curr.left=None
        curr=curr.right

def buildTree(pre, ino):
    if not pre: return None
    root=TreeNode(pre[0]); mid=ino.index(pre[0])
    root.left=buildTree(pre[1:mid+1],ino[:mid])
    root.right=buildTree(pre[mid+1:],ino[mid+1:])
    return root

class Codec:
    def serialize(self, root):
        v=[]
        def dfs(n):
            if not n: v.append('#'); return
            v.append(str(n.val)); dfs(n.left); dfs(n.right)
        dfs(root); return ','.join(v)
    def deserialize(self, data):
        it=iter(data.split(','))
        def dfs():
            val=next(it)
            if val=='#': return None
            n=TreeNode(int(val)); n.left=dfs(); n.right=dfs()
            return n
        return dfs()

def leftView(root):
    if not root: return []
    res,q=[],deque([root])
    while q:
        res.append(q[0].val)
        for _ in range(len(q)):
            n=q.popleft()
            if n.left: q.append(n.left)
            if n.right: q.append(n.right)
    return res

def topView(root):
    if not root: return []
    q=deque([(root,0)]); cm={}
    while q:
        n,hd=q.popleft()
        if hd not in cm: cm[hd]=n.val
        if n.left: q.append((n.left,hd-1))
        if n.right: q.append((n.right,hd+1))
    return [cm[k] for k in sorted(cm)]

def isValidBST(root, lo=float('-inf'), hi=float('inf')):
    if not root: return True
    if root.val<=lo or root.val>=hi: return False
    return isValidBST(root.left,lo,root.val) and isValidBST(root.right,root.val,hi)

def kthSmallest(root, k):
    stack,curr=[],root
    while curr or stack:
        while curr: stack.append(curr); curr=curr.left
        curr=stack.pop(); k-=1
        if k==0: return curr.val
        curr=curr.right

from collections import defaultdict, deque

def bfs(graph, start, n):
    vis=[False]*n; q=deque([start]); vis[start]=True; order=[]
    while q:
        u=q.popleft(); order.append(u)
        for v in graph[u]:
            if not vis[v]: vis[v]=True; q.append(v)
    return order

def dfs(graph, u, vis=None):
    if vis is None: vis=set()
    vis.add(u); res=[u]
    for v in graph[u]:
        if v not in vis: res+=dfs(graph,v,vis)
    return res

def numIslands(grid):
    if not grid: return 0
    R,C=len(grid),len(grid[0]); cnt=0
    def d(r,c):
        if r<0 or r>=R or c<0 or c>=C or grid[r][c]=='0': return
        grid[r][c]='0'
        for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]: d(r+dr,c+dc)
    for r in range(R):
        for c in range(C):
            if grid[r][c]=='1': cnt+=1; d(r,c)
    return cnt

# Undirected — Union Find
def hasCycleUndirected(n, edges):
    par=list(range(n)); rk=[0]*n
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    def union(x,y):
        px,py=find(x),find(y)
        if px==py: return False
        if rk[px]<rk[py]: px,py=py,px
        par[py]=px
        if rk[px]==rk[py]: rk[px]+=1
        return True
    return any(not union(u,v) for u,v in edges)

# Directed — DFS coloring
def hasCycleDirected(graph, n):
    W,G,B=0,1,2; color=[W]*n
    def dfs(u):
        color[u]=G
        for v in graph[u]:
            if color[v]==G: return True
            if color[v]==W and dfs(v): return True
        color[u]=B; return False
    return any(color[u]==W and dfs(u) for u in range(n))

def topoSortBFS(graph, n):
    ind=[0]*n
    for u in graph:
        for v in graph[u]: ind[v]+=1
    q=deque([u for u in range(n) if ind[u]==0]); order=[]
    while q:
        u=q.popleft(); order.append(u)
        for v in graph[u]:
            ind[v]-=1
            if ind[v]==0: q.append(v)
    return order if len(order)==n else []

def topoSortDFS(graph, n):
    vis=[False]*n; stack=[]
    def dfs(u):
        vis[u]=True
        for v in graph[u]:
            if not vis[v]: dfs(v)
        stack.append(u)
    for i in range(n):
        if not vis[i]: dfs(i)
    return stack[::-1]

import heapq
def dijkstra(graph, src, n):
    dist=[float('inf')]*n; dist[src]=0; pq=[(0,src)]
    while pq:
        d,u=heapq.heappop(pq)
        if d>dist[u]: continue
        for v,w in graph[u]:
            if dist[u]+w<dist[v]:
                dist[v]=dist[u]+w; heapq.heappush(pq,(dist[v],v))
    return dist

def bellmanFord(edges, n, src):
    dist=[float('inf')]*n; dist[src]=0
    for _ in range(n-1):
        for u,v,w in edges:
            if dist[u]!=float('inf') and dist[u]+w<dist[v]:
                dist[v]=dist[u]+w
    for u,v,w in edges:
        if dist[u]!=float('inf') and dist[u]+w<dist[v]: return None
    return dist

def floydWarshall(n, edges):
    INF=float('inf')
    dist=[[INF]*n for _ in range(n)]
    for i in range(n): dist[i][i]=0
    for u,v,w in edges: dist[u][v]=w
    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[i][j]=min(dist[i][j],dist[i][k]+dist[k][j])
    return dist

def primMST(graph, n):
    vis=[False]*n; pq=[(0,0)]; total=0
    while pq:
        w,u=heapq.heappop(pq)
        if vis[u]: continue
        vis[u]=True; total+=w
        for v,wt in graph[u]:
            if not vis[v]: heapq.heappush(pq,(wt,v))
    return total

def kruskalMST(n, edges):
    edges.sort(key=lambda x:x[2])
    par=list(range(n)); rk=[0]*n
    def find(x):
        while par[x]!=x: par[x]=par[par[x]]; x=par[x]
        return x
    def union(x,y):
        px,py=find(x),find(y)
        if px==py: return False
        if rk[px]<rk[py]: px,py=py,px
        par[py]=px
        if rk[px]==rk[py]: rk[px]+=1
        return True
    return sum(w for u,v,w in edges if union(u,v))

def isBipartite(graph, n):
    color=[-1]*n
    for s in range(n):
        if color[s]!=-1: continue
        q=deque([s]); color[s]=0
        while q:
            u=q.popleft()
            for v in graph[u]:
                if color[v]==-1: color[v]=1-color[u]; q.append(v)
                elif color[v]==color[u]: return False
    return True

def kosaraju(graph, n):
    vis=[False]*n; order=[]
    def dfs1(u):
        vis[u]=True
        for v in graph[u]:
            if not vis[v]: dfs1(v)
        order.append(u)
    for i in range(n):
        if not vis[i]: dfs1(i)
    rev=defaultdict(list)
    for u in graph:
        for v in graph[u]: rev[v].append(u)
    vis=[False]*n; sccs=[]
    def dfs2(u,comp):
        vis[u]=True; comp.append(u)
        for v in rev[u]:
            if not vis[v]: dfs2(v,comp)
    for u in reversed(order):
        if not vis[u]:
            comp=[]; dfs2(u,comp); sccs.append(comp)
    return sccs

def orangesRotting(grid):
    R,C=len(grid),len(grid[0]); q=deque(); fresh=0
    for r in range(R):
        for c in range(C):
            if grid[r][c]==2: q.append((r,c,0))
            elif grid[r][c]==1: fresh+=1
    time=0
    while q:
        r,c,t=q.popleft()
        for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and grid[nr][nc]==1:
                grid[nr][nc]=2; fresh-=1; time=t+1
                q.append((nr,nc,t+1))
    return time if fresh==0 else -1

def ladderLength(begin, end, wordList):
    ws=set(wordList)
    if end not in ws: return 0
    q=deque([(begin,1)])
    while q:
        word,steps=q.popleft()
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nw=word[:i]+c+word[i+1:]
                if nw==end: return steps+1
                if nw in ws: ws.discard(nw); q.append((nw,steps+1))
    return 0

def canFinish(numCourses, prereqs):
    graph=defaultdict(list); ind=[0]*numCourses
    for a,b in prereqs: graph[b].append(a); ind[a]+=1
    q=deque([i for i in range(numCourses) if ind[i]==0]); cnt=0
    while q:
        u=q.popleft(); cnt+=1
        for v in graph[u]:
            ind[v]-=1
            if ind[v]==0: q.append(v)
    return cnt==numCourses

def search(nums: list[int], target: int) -> int:
    l, r = 0, len(nums) - 1
    while l <= r:
        mid = (l + r) // 2
        if nums[mid] == target: return mid

        # Left sorted portion
        if nums[l] <= nums[mid]:
            if target > nums[mid] or target < nums[l]:
                l = mid + 1
            else:
                r = mid - 1
        # Right sorted portion
        else:
            if target < nums[mid] or target > nums[r]:
                r = mid - 1
            else:
                l = mid + 1
    return -1

def findMin(nums: list[int]) -> int:
    res = nums[0]
    l, r = 0, len(nums) - 1
    while l <= r:
        if nums[l] < nums[r]:
            res = min(res, nums[l])
            break
        mid = (l + r) // 2
        res = min(res, nums[mid])
        if nums[mid] >= nums[l]:
            l = mid + 1
        else:
            r = mid - 1
    return res

import math

def minEatingSpeed(piles: list[int], h: int) -> int:
    l, r = 1, max(piles)
    res = r
    while l <= r:
        k = (l + r) // 2
        hours = 0
        for p in piles:
            hours += math.ceil(p / k)

        if hours <= h:
            res = min(res, k)
            r = k - 1
        else:
            l = k + 1
    return res

def hasCycle(head) -> bool:
    slow, fast = head, head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow == fast:
            return True
    return False

