class Trie:
    def __init__(self): self.root=TrieNode()
    def insert(self, word):
        n=self.root
        for c in word:
            if c not in n.ch: n.ch[c]=TrieNode()
            n=n.ch[c]
        n.end=True
    def search(self, word):
        n=self._find(word)
        return n is not None and n.end
    def startsWith(self, pre):
        return self._find(pre) is not None
    def _find(self, w):
        n=self.root
        for c in w:
            if c not in n.ch: return None
            n=n.ch[c]
        return n

def findWords(board, words):
    root={}
    for w in words:
        node=root
        for c in w: node=node.setdefault(c,{})
        node['#']=w
    R,C=len(board),len(board[0]); res=[]
    def dfs(r,c,par):
        ch=board[r][c]; node=par[ch]
        if '#' in node: res.append(node.pop('#'))
        board[r][c]='.'
        for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr,nc=r+dr,c+dc
            if 0<=nr<R and 0<=nc<C and board[nr][nc] in node:
                dfs(nr,nc,node)
        board[r][c]=ch
        if not node: par.pop(ch)
    for r in range(R):
        for c in range(C):
            if board[r][c] in root: dfs(r,c,root)
    return res

