class DSU:
    def __init__(self):
        self.par = {}
    def find(self, x):
        if x not in self.par:
            self.par[x] = x
        if x != self.par[x]:
            self.par[x] = self.find(self.par[x])
        return self.par[x]
    def union(self, x, y):
        self.par[self.find(x)] = self.find(y)

def accountsMerge(accounts: list[list[str]]) -> list[list[str]]:
    dsu = DSU()
    email_to_name = {}

    # 1. Union emails in the same account
    for acc in accounts:
        name = acc[0]
        first_email = acc[1]
        for email in acc[1:]:
            dsu.union(first_email, email)
            email_to_name[email] = name

    # 2. Group emails by their DSU root
    import collections
    merged = collections.defaultdict(list)
    for email in email_to_name:
        merged[dsu.find(email)].append(email)

    # 3. Format result
    return [[email_to_name[root]] + sorted(emails) for root, emails in merged.items()]

def validTree(n: int, edges: list[list[int]]) -> bool:
    if len(edges) != n - 1:
        return False

    par = [i for i in range(n)]

    def find(x):
        if x != par[x]:
            par[x] = find(par[x])
        return par[x]

    def union(x, y):
        p1, p2 = find(x), find(y)
        if p1 == p2:
            return False
        par[p1] = p2
        return True

    for u, v in edges:
        if not union(u, v):
            return False

    return True

def makeConnected(n: int, connections: list[list[int]]) -> int:
    if len(connections) < n - 1:
        return -1

    par = [i for i in range(n)]

    def find(x):
        if x != par[x]:
            par[x] = find(par[x])
        return par[x]

    components = n
    for u, v in connections:
        p1, p2 = find(u), find(v)
        if p1 != p2:
            par[p1] = p2
            components -= 1

    return components - 1
